package com.yuegang.zhihui.training.application;
import com.fasterxml.jackson.core.type.TypeReference;import com.fasterxml.jackson.databind.ObjectMapper;import com.yuegang.zhihui.common.core.*;import com.yuegang.zhihui.training.api.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.nio.file.*;import java.security.*;import java.sql.*;import java.util.*;import javax.sql.DataSource;import org.apache.tika.Tika;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.web.multipart.MultipartFile;
public final class TrainingContentService{private static final Set<String>ALLOWED=Set.of("application/pdf","application/vnd.openxmlformats-officedocument.wordprocessingml.document","text/plain","text/markdown");private final JdbcTemplate jdbc;private final ObjectMapper json;private final Path root;private final Tika tika=new Tika();public TrainingContentService(DataSource d,ObjectMapper o,String storage){jdbc=new JdbcTemplate(d);json=o;root=Path.of(storage).toAbsolutePath().normalize();try{Files.createDirectories(root);}catch(IOException e){throw new IllegalStateException("training storage unavailable",e);}}public CourseView createCourse(SaveCourseRequest r){long id=next();jdbc.update("INSERT INTO training_course(id,title,description,pass_score,estimated_minutes) VALUES(?,?,?,?,?)",id,r.title(),r.description(),r.passScore(),r.estimatedMinutes());return course(id);}public CourseView publish(String course,long version){long id=id(course);if(jdbc.update("UPDATE training_course SET status='PUBLISHED',version=version+1 WHERE id=? AND version=? AND status='DRAFT'",id,version)!=1)throw new BusinessException(ErrorCode.BUSINESS_CONFLICT);return course(id);}public List<CourseView>courses(boolean publishedOnly){return jdbc.query("SELECT * FROM training_course"+(publishedOnly?" WHERE status='PUBLISHED'":"")+" ORDER BY updated_at DESC",(r,n)->mapCourse(r));}public ChapterView createChapter(SaveChapterRequest r){long id=next();jdbc.update("INSERT INTO training_chapter(id,course_id,title,sequence_no,minimum_active_seconds) VALUES(?,?,?,?,?)",id,id(r.courseId()),r.title(),r.sequenceNo(),r.minimumActiveSeconds());return chapter(id);}public List<ChapterView>chapters(String course){return jdbc.query("SELECT * FROM training_chapter WHERE course_id=? ORDER BY sequence_no",(r,n)->mapChapter(r),id(course));}public GateView createGate(SaveGateRequest r){long id=next();jdbc.update("INSERT INTO training_gate(id,chapter_id,title,pass_score,maximum_attempts) VALUES(?,?,?,?,?)",id,id(r.chapterId()),r.title(),r.passScore(),r.maximumAttempts());return new GateView(Long.toString(id),r.chapterId(),r.title(),r.passScore(),r.maximumAttempts());}public QuestionView createQuestion(SaveQuestionRequest r){long id=next();String options=write(r.options()==null?List.of():r.options());jdbc.update("INSERT INTO training_question(id,gate_id,question_type,stem,options_json,correct_answer_hash,explanation,score) VALUES(?,?,?,?,?,?,?,?)",id,id(r.gateId()),r.type(),r.stem(),options,hash(r.correctAnswer()),r.explanation(),r.score());return new QuestionView(Long.toString(id),r.gateId(),r.type(),r.stem(),r.options(),r.explanation(),r.score());}public List<QuestionView>questions(String gate){return jdbc.query("SELECT * FROM training_question WHERE gate_id=? ORDER BY id",(r,n)->new QuestionView(Long.toString(r.getLong("id")),Long.toString(r.getLong("gate_id")),r.getString("question_type"),r.getString("stem"),read(r.getString("options_json")),r.getString("explanation"),r.getInt("score")),id(gate));}public TrainingDocumentView upload(String chapter,MultipartFile file){if(file==null||file.isEmpty()||file.getSize()>50L*1024*1024)throw new BusinessException(ErrorCode.VALIDATION_ERROR);long chapterId=id(chapter),documentId=next();String original=Path.of(Objects.requireNonNullElse(file.getOriginalFilename(),"document")).getFileName().toString();try{byte[]bytes=file.getBytes();String media=tika.detect(bytes,original);if(!ALLOWED.contains(media))throw new BusinessException(ErrorCode.VALIDATION_ERROR);String sha=HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(bytes));Path target=root.resolve(Long.toString(documentId)+"-"+sha.substring(0,16)).normalize();if(!target.startsWith(root))throw new BusinessException(ErrorCode.VALIDATION_ERROR);Files.write(target,bytes,StandardOpenOption.CREATE_NEW);jdbc.update("INSERT INTO training_document(id,chapter_id,file_name,media_type,storage_key,sha256,size_bytes) VALUES(?,?,?,?,?,?,?)",documentId,chapterId,original,media,target.getFileName().toString(),sha,bytes.length);return new TrainingDocumentView(Long.toString(documentId),chapter,original,media,bytes.length,"ACTIVE");}catch(BusinessException e){throw e;}catch(Exception e){throw new BusinessException(ErrorCode.INTERNAL_ERROR);}}private CourseView course(long id){return jdbc.query("SELECT * FROM training_course WHERE id=?",r->{if(!r.next())throw new BusinessException(ErrorCode.RESOURCE_NOT_FOUND);return mapCourse(r);},id);}private ChapterView chapter(long id){return jdbc.query("SELECT * FROM training_chapter WHERE id=?",r->{if(!r.next())throw new BusinessException(ErrorCode.RESOURCE_NOT_FOUND);return mapChapter(r);},id);}private static CourseView mapCourse(ResultSet r)throws SQLException{return new CourseView(Long.toString(r.getLong("id")),r.getString("title"),r.getString("description"),r.getString("status"),r.getInt("pass_score"),r.getInt("estimated_minutes"),r.getLong("version"));}private static ChapterView mapChapter(ResultSet r)throws SQLException{return new ChapterView(Long.toString(r.getLong("id")),Long.toString(r.getLong("course_id")),r.getString("title"),r.getInt("sequence_no"),r.getInt("minimum_active_seconds"),r.getLong("version"));}private String write(Object x){try{return json.writeValueAsString(x);}catch(Exception e){throw new BusinessException(ErrorCode.VALIDATION_ERROR);}}private List<String>read(String x){try{return json.readValue(x,new TypeReference<>(){});}catch(Exception e){return List.of();}}private static String hash(String value){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(value.strip().toLowerCase(Locale.ROOT).getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}private static long next(){return UUID.randomUUID().getMostSignificantBits()&Long.MAX_VALUE;}private static long id(String x){try{long v=Long.parseLong(x);if(v<=0)throw new NumberFormatException();return v;}catch(Exception e){throw new BusinessException(ErrorCode.VALIDATION_ERROR);}}}
